mapper.select:
SELECT r.reservation_code AS reservationCode, r.people_number AS reservationNum, TO_CHAR(r.reservation_date, 'YYYY.MM.DD HH24:MI') AS reservationDate, TO_CHAR(s.class_date, 'YYYY.MM.DD') || ' ' || s.start_time AS classDate,
/* 💡 상단용: DB의 예약/수강 상태(r.status) 그대로 조회 */ r.status AS classStatus,
r.price AS totalPrice,
c.class_code AS classCode, c.operator_code AS operatorCode, c.category_code AS categoryCode, c.name AS className, img.image AS classImg, c.price AS classPrice, c.address AS address, c.address2 AS address2, c.single_introduce AS singleIntroduce, c.introduce AS introduce, TO_CHAR(c.write_date, 'YYYY.MM.DD HH24:MI') AS writeDate,
/* 💡 하단용: DB의 결제 상태(p.status) 그대로 조회 */ p.payment_code AS paymentCode, p.amount AS finalPrice, p.means AS paymentMethod, TO_CHAR(p.payment_date, 'YYYY.MM.DD HH24:MI') AS paymentDate, p.status AS paymentStatus, p.PG_code AS pgCode, p.refund AS refund, TO_CHAR(p.refund_date, 'YYYY.MM.DD HH24:MI') AS refundDate FROM reservation r JOIN class c ON r.class_code = c.class_code LEFT JOIN schedule s ON r.schedule_code = s.schedule_code LEFT JOIN class_img img ON c.class_code = img.class_code AND img.type = '대표' AND img.sort_order = 1 LEFT JOIN payment p ON r.reservation_code = p.reservation_code WHERE r.reservation_code = TO_NUMBER(#{reservationCode})
